-- World Airport Database - SQL Export
-- Generated from OurAirports open data
-- 9056 airports, all with IATA codes

CREATE TABLE IF NOT EXISTS airports (
  id INT PRIMARY KEY,
  iata VARCHAR(3) NOT NULL,
  icao VARCHAR(4),
  type VARCHAR(50) NOT NULL,
  name VARCHAR(255) NOT NULL,
  lat DECIMAL(10, 6),
  lon DECIMAL(10, 6),
  elevation INT,
  continent CHAR(2),
  country VARCHAR(100),
  iso_country CHAR(2),
  municipality VARCHAR(100),
  scheduled BOOLEAN,
  score INT,
  INDEX idx_iata (iata),
  INDEX idx_icao (icao),
  INDEX idx_country (iso_country),
  INDEX idx_continent (continent)
);

